style.css:
@-moz-document domain("x.com"), domain("twitter.com") {
input,
  /* Primary text element classes */
  .r-poiln3,
  /* Specific target for the tweet composition area (Simplified to fix parser error with :has()) */
  [data-testid="tweetTextarea_0_label"] .r-xoduu5,
  /* Tweet body text */
  [data-testid="tweet"] [data-testid="tweetText"],
  /* Twitter's custom font class */
  .font-chirp {
    /* Now includes the imported font and a sans-serif fallback */
    font-family: Vazirmatn, sans-serif !important;
  }
}
